 public static Record[][] HashTable = new Record[100][10];
 public static void InitialiseHashTable(){
        Record EmptyRecord = new Record(-1,"-1");
        for(Integer X = 0; X < 100; X++){
              for(Integer Y = 0; Y < 10; Y++){
                     HashTable[X][Y] = EmptyRecord;
              }
        }
 }
