      While Not FileReader.EndOfStream
           Line = FileReader.ReadLine()
           Data = Split(Line, ",")
           TheRecord = New Record(Integer.Parse(Data(0)), Data(1))
           InsertData(TheRecord)
      End While
      FileReader.Close()
 End Sub
